package in.carelink;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.sql.*;
import java.util.*;
@RestController @RequestMapping("/api")
public class ApiController {
 private final JdbcTemplate db;
 public ApiController(JdbcTemplate db){this.db=db;}
 private Map<String,Object> map(ResultSet r)throws SQLException{Map<String,Object> m=new LinkedHashMap<>();for(int i=1;i<=r.getMetaData().getColumnCount();i++)m.put(r.getMetaData().getColumnLabel(i),r.getObject(i));return m;}
 private List<Map<String,Object>> list(String q,Object...a){return db.query(q,(r,n)->map(r),a);}
 private Map<String,Object> one(String q,Object...a){try{return db.queryForObject(q,(r,n)->map(r),a);}catch(Exception e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found");}}
 private void req(Map<String,Object>b,String...ks){for(String k:ks)if(b.get(k)==null||b.get(k).toString().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Missing field: "+k);}
 private void audit(String action,String type,Object id,String details){db.update("INSERT INTO audit_logs(actor,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)","demo-user",action,type,String.valueOf(id),details);}
 @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","ok","service","CareLink API","database",db.queryForObject("SELECT 1",Integer.class));}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){return Map.of("patients",db.queryForObject("SELECT COUNT(*) FROM patients",Integer.class),"doctors",db.queryForObject("SELECT COUNT(*) FROM doctors",Integer.class),"appointments",db.queryForObject("SELECT COUNT(*) FROM appointments",Integer.class),"records",db.queryForObject("SELECT COUNT(*) FROM medical_records",Integer.class),"bills",db.queryForObject("SELECT COUNT(*) FROM bills",Integer.class),"consents",db.queryForObject("SELECT COUNT(*) FROM patient_consents WHERE status='Granted' AND expires_at>NOW()",Integer.class));}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Map<String,String>b){String role=b.getOrDefault("role","");String email=b.getOrDefault("email","");String pass=b.getOrDefault("password","");Map<String,String[]> users=Map.of("admin",new String[]{"admin@carelink.in","admin123","CareLink Admin"},"doctor",new String[]{"doctor@carelink.in","doctor123","Dr. Neha Kulkarni"},"patient",new String[]{"patient@carelink.in","patient123","Aarav Mehta"});String[]u=users.get(role);if(u==null||!u[0].equalsIgnoreCase(email)||!u[1].equals(pass))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid demo credentials");return Map.of("role",role,"email",email,"name",u[2],"demo",true);}
 @GetMapping("/patients") public List<Map<String,Object>> patients(){return list("SELECT * FROM patients ORDER BY patient_id DESC");}
 @PostMapping("/patients") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> addPatient(@RequestBody Map<String,Object>b){req(b,"health_id","full_name");db.update("INSERT INTO patients(health_id,full_name,date_of_birth,gender,phone,email,address,blood_group) VALUES(?,?,?,?,?,?,?,?)",b.get("health_id"),b.get("full_name"),b.get("date_of_birth"),b.get("gender"),b.get("phone"),b.get("email"),b.get("address"),b.get("blood_group"));long id=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);audit("CREATE","patient",id,"Patient registered");return one("SELECT * FROM patients WHERE patient_id=?",id);}
 @DeleteMapping("/patients/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deletePatient(@PathVariable long id){db.update("DELETE FROM patients WHERE patient_id=?",id);audit("DELETE","patient",id,"Patient deleted");}
 @GetMapping("/doctors") public List<Map<String,Object>> doctors(){return list("SELECT * FROM doctors ORDER BY doctor_id DESC");}
 @PostMapping("/doctors") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> addDoctor(@RequestBody Map<String,Object>b){req(b,"full_name");db.update("INSERT INTO doctors(full_name,specialization,phone,email,department,consultation_fee) VALUES(?,?,?,?,?,?)",b.get("full_name"),b.get("specialization"),b.get("phone"),b.get("email"),b.get("department"),b.getOrDefault("consultation_fee",0));long id=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);audit("CREATE","doctor",id,"Doctor added");return one("SELECT * FROM doctors WHERE doctor_id=?",id);}
 @GetMapping("/appointments") public List<Map<String,Object>> appointments(){return list("SELECT a.*,p.full_name patient_name,d.full_name doctor_name FROM appointments a JOIN patients p ON p.patient_id=a.patient_id JOIN doctors d ON d.doctor_id=a.doctor_id ORDER BY appointment_date DESC");}
 @PostMapping("/appointments") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> addAppointment(@RequestBody Map<String,Object>b){req(b,"patient_id","doctor_id","appointment_date");db.update("INSERT INTO appointments(patient_id,doctor_id,appointment_date,status,reason) VALUES(?,?,?,COALESCE(?, 'Scheduled'),?)",b.get("patient_id"),b.get("doctor_id"),b.get("appointment_date"),b.get("status"),b.get("reason"));long id=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);audit("CREATE","appointment",id,"Appointment scheduled");return one("SELECT * FROM appointments WHERE appointment_id=?",id);}
 @GetMapping("/records") public List<Map<String,Object>> records(){return list("SELECT mr.*,p.full_name patient_name,d.full_name doctor_name FROM medical_records mr JOIN patients p ON p.patient_id=mr.patient_id LEFT JOIN doctors d ON d.doctor_id=mr.doctor_id ORDER BY record_date DESC");}
 @PostMapping("/records") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> addRecord(@RequestBody Map<String,Object>b){req(b,"patient_id","record_date","diagnosis","hospital_name");db.update("INSERT INTO medical_records(patient_id,doctor_id,record_date,diagnosis,notes,hospital_name,record_category) VALUES(?,?,?,?,?,?,?)",b.get("patient_id"),b.get("doctor_id"),b.get("record_date"),b.get("diagnosis"),b.get("notes"),b.get("hospital_name"),b.getOrDefault("record_category","General"));long id=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);audit("CREATE","medical_record",id,"Record added");return one("SELECT * FROM medical_records WHERE record_id=?",id);}
 @GetMapping("/medicines") public List<Map<String,Object>> medicines(){return list("SELECT * FROM medicines ORDER BY name");}
 @GetMapping("/admissions") public List<Map<String,Object>> admissions(){return list("SELECT a.*,p.full_name patient_name FROM admissions a JOIN patients p ON p.patient_id=a.patient_id ORDER BY admission_id DESC");}
 @GetMapping("/bills") public List<Map<String,Object>> bills(){return list("SELECT b.*,p.full_name patient_name FROM bills b JOIN patients p ON p.patient_id=b.patient_id ORDER BY bill_id DESC");}
 @GetMapping("/consents") public List<Map<String,Object>> consents(){return list("SELECT * FROM patient_consents ORDER BY consent_id DESC");}
 @PostMapping("/consents") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> addConsent(@RequestBody Map<String,Object>b){req(b,"patient_id","health_id","requesting_hospital","record_scope","expires_at");db.update("INSERT INTO patient_consents(patient_id,health_id,requesting_hospital,record_scope,granted_at,expires_at,status) VALUES(?,?,?,?,NOW(),?,'Granted')",b.get("patient_id"),b.get("health_id"),b.get("requesting_hospital"),b.get("record_scope"),b.get("expires_at"));long id=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);audit("GRANT_CONSENT","consent",id,"Consent granted");return one("SELECT * FROM patient_consents WHERE consent_id=?",id);}
 @PatchMapping("/consents/{id}/revoke") public Map<String,Object> revoke(@PathVariable long id){db.update("UPDATE patient_consents SET status='Revoked' WHERE consent_id=?",id);audit("REVOKE_CONSENT","consent",id,"Consent revoked");return one("SELECT * FROM patient_consents WHERE consent_id=?",id);}
 @GetMapping("/audit-logs") public List<Map<String,Object>> logs(){return list("SELECT * FROM audit_logs ORDER BY audit_id DESC LIMIT 200");}
}